window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4493306d8153b81a"]={"versions": [{"id": "FIG-4493306d8153b81a", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Scheduling-Diagramm zur zyklusbasierten Ausführung der FlexRay-Netzwerkmanagement-Hauptfunktion (<code>FrNm_MainFunction</code>) im AUTOSAR-Architekturkontext zwischen FrNm, FlexRay Interface (FrIf) und dem Kommunikationszyklus des FlexRay-Busses.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>FlexRay-Buszyklus</strong>: Zeitachse $t$ mit aufeinanderfolgenden Zyklen <code>FlexRay Cycle N</code> und <code>FlexRay Cycle N+1</code>.</li>\n<li><strong>Frames</strong>:</li>\n<li><code>Frame with other NM-PDU (RX)</code>: Hellgrün markierte Kommunikations-Frames anderer Steuergeräte mit NM-PDUs.</li>\n<li><code>Frame without NM-PDU</code>: Weiß/unfarbig markierte Frames ohne Netzwerkmanagement-Daten.</li>\n<li>Sende-Frame der eigenen NM-PDU: Dunkelgrün hervorgehobener Frame im jeweiligen Zyklus.</li>\n<li><strong>Schnittstellen- und Timing-Parameter</strong>:</li>\n<li><code>Point in time where all NM-PDUs of the actual cycle are available</code>: Grenze nach Empfang aller NM-PDUs des aktuellen Zyklus.</li>\n<li><code>FrIf RX-Time</code>: Zeitversatz/Verarbeitungszeit im FrIf für den Empfang bis zur Bereitstellung an FrNm.</li>\n<li><code>Point in time where the own NM-PDU must be provided</code>: Deadline für die Bereitstellung der eigenen Sende-PDU an das FrIf.</li>\n<li><code>FrIf TX-Time</code>: Vorlaufzeit des FrIf vor der tatsächlichen Sendezeit auf dem Bus.</li>\n<li><code>FrNm MainFunction activation window</code>: Zulässiges Ausführungsfenster für den Taskaufruf der FrNm-Hauptfunktion (gelber Block) mit Jitter-Toleranzband (gestrichelte Linie).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Innerhalb von <code>FlexRay Cycle N</code> empfängt das FlexRay-Interface mehrere Frames; der Empfang aller relevanten NM-PDUs ist an einem definierten Zeitpunkt abgeschlossen.</li>\n<li>Nach Ablauf von <code>FrIf RX-Time</code> stehen alle NM-PDUs des aktuellen Zyklus zur Auswertung bereit.</li>\n<li>Hierdurch öffnet sich das Aktivierungsfenster (<code>FrNm MainFunction activation window</code>), das über die Grenze von Zyklus N zu Zyklus N+1 reicht.</li>\n<li>Die <code>FrNm MainFunction</code> wird innerhalb dieses Fensters ausgeführt (gelber Block), verarbeitet die empfangenen NM-PDUs und berechnet den NM-Status sowie die eigene NM-PDU für Zyklus N+1.</li>\n<li>Das Aktivierungsfenster schließt an dem Zeitpunkt, an dem die eigene NM-PDU spätestens bereitgestellt sein muss (<code>Point in time where the own NM-PDU must be provided</code>).</li>\n<li>Nach Ablauf der Vorlaufzeit <code>FrIf TX-Time</code> überträgt das FlexRay Interface die eigene NM-PDU im dafür vorgesehenen statischen/dynamischen Slot (dunkelgrüner Frame) in <code>FlexRay Cycle N+1</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert die harte zeitliche Kopplung und Scheduling-Bedingung für das Task-Design der <code>FrNm_MainFunction</code> in synchronen FlexRay-Clustern.</li>\n<li>Das OS-Scheduling bzw. der BSW-Scheduler muss sicherstellen, dass die Aktivierung und Abarbeitung der FrNm-Hauptfunktion strikt innerhalb des Fensters zwischen $(t_{\\text{RX\\_all}} + \\text{FrIf RX-Time})$ und $(t_{\\text{TX\\_own}} - \\text{FrIf TX-Time})$ erfolgt.</li>\n<li>Eine Verletzung des Aktivierungsfensters führt zu Zyklusverzug (Verwendung veralteter RX-NM-Daten oder Ausfall/Verzug der eigenen TX-NM-PDU im folgenden FlexRay-Zyklus).</li>\n</ul>"}, {"id": "FIG-bf90ed422721c115", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Scheduling-Diagramm zur zyklusbasierten Ausführung der FlexRay-Netzwerkmanagement-Hauptfunktion (<code>FrNm_MainFunction</code>) im AUTOSAR-Architekturkontext zwischen FrNm, FlexRay Interface (FrIf) und dem Kommunikationszyklus des FlexRay-Busses.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>FlexRay-Buszyklus</strong>: Zeitachse $t$ mit aufeinanderfolgenden Zyklen <code>FlexRay Cycle N</code> und <code>FlexRay Cycle N+1</code>.</li>\n<li><strong>Frames</strong>:</li>\n<li><code>Frame with other NM-PDU (RX)</code>: Hellgrün markierte Kommunikations-Frames anderer Steuergeräte mit NM-PDUs.</li>\n<li><code>Frame without NM-PDU</code>: Weiß/unfarbig markierte Frames ohne Netzwerkmanagement-Daten.</li>\n<li>Sende-Frame der eigenen NM-PDU: Dunkelgrün hervorgehobener Frame im jeweiligen Zyklus.</li>\n<li><strong>Schnittstellen- und Timing-Parameter</strong>:</li>\n<li><code>Point in time where all NM-PDUs of the actual cycle are available</code>: Grenze nach Empfang aller NM-PDUs des aktuellen Zyklus.</li>\n<li><code>FrIf RX-Time</code>: Zeitversatz/Verarbeitungszeit im FrIf für den Empfang bis zur Bereitstellung an FrNm.</li>\n<li><code>Point in time where the own NM-PDU must be provided</code>: Deadline für die Bereitstellung der eigenen Sende-PDU an das FrIf.</li>\n<li><code>FrIf TX-Time</code>: Vorlaufzeit des FrIf vor der tatsächlichen Sendezeit auf dem Bus.</li>\n<li><code>FrNm MainFunction activation window</code>: Zulässiges Ausführungsfenster für den Taskaufruf der FrNm-Hauptfunktion (gelber Block) mit Jitter-Toleranzband (gestrichelte Linie).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Innerhalb von <code>FlexRay Cycle N</code> empfängt das FlexRay-Interface mehrere Frames; der Empfang aller relevanten NM-PDUs ist an einem definierten Zeitpunkt abgeschlossen.</li>\n<li>Nach Ablauf von <code>FrIf RX-Time</code> stehen alle NM-PDUs des aktuellen Zyklus zur Auswertung bereit.</li>\n<li>Hierdurch öffnet sich das Aktivierungsfenster (<code>FrNm MainFunction activation window</code>), das über die Grenze von Zyklus N zu Zyklus N+1 reicht.</li>\n<li>Die <code>FrNm MainFunction</code> wird innerhalb dieses Fensters ausgeführt (gelber Block), verarbeitet die empfangenen NM-PDUs und berechnet den NM-Status sowie die eigene NM-PDU für Zyklus N+1.</li>\n<li>Das Aktivierungsfenster schließt an dem Zeitpunkt, an dem die eigene NM-PDU spätestens bereitgestellt sein muss (<code>Point in time where the own NM-PDU must be provided</code>).</li>\n<li>Nach Ablauf der Vorlaufzeit <code>FrIf TX-Time</code> überträgt das FlexRay Interface die eigene NM-PDU im dafür vorgesehenen statischen/dynamischen Slot (dunkelgrüner Frame) in <code>FlexRay Cycle N+1</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert die harte zeitliche Kopplung und Scheduling-Bedingung für das Task-Design der <code>FrNm_MainFunction</code> in synchronen FlexRay-Clustern.</li>\n<li>Das OS-Scheduling bzw. der BSW-Scheduler muss sicherstellen, dass die Aktivierung und Abarbeitung der FrNm-Hauptfunktion strikt innerhalb des Fensters zwischen $(t_{\\text{RX\\_all}} + \\text{FrIf RX-Time})$ und $(t_{\\text{TX\\_own}} - \\text{FrIf TX-Time})$ erfolgt.</li>\n<li>Eine Verletzung des Aktivierungsfensters führt zu Zyklusverzug (Verwendung veralteter RX-NM-Daten oder Ausfall/Verzug der eigenen TX-NM-PDU im folgenden FlexRay-Zyklus).</li>\n</ul>"}], "trans": [{"from": "FIG-4493306d8153b81a", "to": "FIG-bf90ed422721c115", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Bildzuschnitt am unteren Rand korrigiert (Legendenreste abgeschnitten).</li>\n<li>Rendering und Schriftglättung des Diagramms neu aufgebaut.</li>\n</ul>"}]};
